    title: 'Quantum Computing',
    content: 'Quantum computing harnesses quantum mechanics to process information in fundamentally new ways.',
  },
  {
    id: 2,
    title: 'Artificial Intelligence',
    content: 'AI systems can perform tasks that typically require human intelligence, such as visual perception and decision-making.',
    image: 'https://placehold.co/400x300/333/fff?text=AI',
  },
  {
    id: 3,
    title: 'Blockchain Technology',
    content: 'Blockchain is a distributed ledger technology that enables secure, transparent, and tamper-proof record-keeping.',
  },
];

const meta = preview.meta({
  component: ArticleList,
  tags: ['ai-generated'],
});

export const Default = meta.story({
  args: {
    articles: mockArticles,
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('Quantum Computing')).toBeVisible();
    await expect(canvas.getByText('Artificial Intelligence')).toBeVisible();
    await expect(canvas.getByText('Blockchain Technology')).toBeVisible();
  },
});

