  args: {
    article: mockArticle,
  },
  play: async ({ canvas, userEvent }) => {
    const likeButton = canvas.getByRole('button', { name: /like article/i });
    await expect(likeButton).toBeVisible();
    await userEvent.click(likeButton);
    await expect(likeButton).toBeVisible();
  },
};

export const CssCheck: Story = {
  args: {
    article: mockArticle,
  },
  play: async ({ canvas }) => {
    const heading = canvas.getByRole('heading', { name: /aurora borealis/i });
    await expect(heading).toBeVisible();
    const style = getComputedStyle(heading);
    // text-2xl font-bold — Tailwind should apply bold weight
    await expect(style.fontWeight).toBe('700');
  },
};

