    // Initially liked (red bg)
    await expect(likeButton.className).toContain('bg-red-500');
    await userEvent.click(likeButton);
    // After toggle, should no longer be red
    await waitFor(() => {
      expect(likeButton.className).not.toContain('bg-red-500');
    });
  },
};

